INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs) VALUES
  (59, 1, 'Primary-Replica 복제와 Galera 의 차이 알기', '일반 MariaDB 복제(Primary-Replica)와 **Galera Cluster** 의 가장 큰 차이는 무엇일까요?', '"어느 노드에 쓸 수 있는가"를 비교해 보세요.', NULL, NULL, '[]', 'choice', '["일반 복제는 Primary 에만 쓰고 Replica 는 읽기 전용인 반면, Galera 는 **모든 노드에 읽기·쓰기**가 가능한 Multi-Master 동기 복제 클러스터이다", "Galera 는 읽기 전용 복제이다", "일반 복제가 동기식이고 Galera 는 비동기식이다", "Galera 는 노드를 하나만 둘 수 있다"]', 0, '일반 복제는 보통 비동기이고 쓰기는 Primary 로만 갑니다. **Galera** 는 모든 노드가 Primary 처럼 동작하는 Multi-Master 이고 동기 복제(virtually synchronous)입니다. 노드 하나가 죽어도 데이터 유실이 없다는 장점이 있지만, 같은 행을 동시에 수정하는 **충돌**을 처리해야 합니다.', NULL, NULL, NULL, NULL),
  (59, 2, 'Galera 동기 복제의 의미 알기', 'Galera 는 "동기 복제"입니다. 트랜잭션이 커밋될 때 보장되는 것으로 알맞은 것은 무엇일까요?', '"받았다"와 "디스크에 적용했다"는 같은 말이 아닙니다.', NULL, NULL, '[]', 'choice', '["모든 노드의 디스크에 같은 순간 적용이 끝난다", "모든 노드가 그 트랜잭션(Write-Set)을 **받았음**을 보장하지만, 모든 노드가 디스크에 **적용했음**까지 보장하지는 않는다", "받는 노드가 하나라도 있으면 커밋된다", "커밋 후 몇 분 뒤에 전파된다"]', 1, 'WSREP 는 **virtually synchronous** 입니다. 커밋 시점에 모든 노드가 Write-Set 을 받았고 충돌 검증(Certification)을 통과했음은 보장하지만, 실제 적용은 각 노드의 큐에서 순서대로 이뤄집니다. 그래서 `wsrep_local_recv_queue` 가 쌓이면 적용이 밀리고 있다는 신호입니다.', NULL, NULL, NULL, NULL),
  (59, 3, 'Galera 의 충돌 처리 방식 알기', 'Galera 에서 **두 노드가 같은 PK(`id=1`)의 행을 거의 동시에 수정**했습니다. 어떻게 처리될까요?', '낙관적 방식: 일단 쓰기를 허용하고 커밋 시점에 검증합니다.', NULL, NULL, '[]', 'choice', '["두 수정이 자동으로 병합된다", "두 노드 모두 롤백되고 데이터는 그대로이다", "커밋 시점의 Certification 에서 충돌이 감지되어, **나중에 커밋을 시도한 쪽이 롤백**된다", "먼저 수정한 노드 하나만 영원히 잠긴다"]', 2, 'Galera 는 **낙관적 동시성 제어**(Certification-based Replication)를 씁니다. 쓰기를 막지 않고 허용한 뒤, 커밋 시 변경한 행의 **PK 집합(Write-Set)** 을 모든 노드가 검사합니다. 같은 구간에서 같은 PK 를 수정한 트랜잭션이 둘 이상이면 충돌로 보고 나중 것을 롤백합니다. 그래서 애플리케이션은 롤백(deadlock 오류)에 대비한 재시도가 필요합니다.', NULL, NULL, NULL, NULL),
  (59, 4, 'Galera 의 AUTO_INCREMENT 설정 알기', '3노드 Galera 에서 노드마다 독립적으로 INSERT 를 하면 AUTO_INCREMENT 가 겹쳐 **PK 충돌**이 날 수 있습니다. 이를 막는 설정으로 알맞은 것은 무엇일까요?', '간격과 시작점을 노드마다 다르게 나눕니다.', NULL, NULL, '[]', 'choice', '["모든 노드의 offset 을 1 로 맞춘다", "AUTO_INCREMENT 를 끄고 PK 를 없앤다", "increment 를 0 으로 둔다", "`auto_increment_increment` 를 노드 수(3)로 두고, 노드마다 `auto_increment_offset` 을 1, 2, 3 으로 다르게 준다"]', 3, '이렇게 하면 Node1 은 1,4,7…, Node2 는 2,5,8…, Node3 은 3,6,9… 처럼 **서로 겹치지 않는 값**을 만듭니다. 값이 연속적이지 않은 것은 정상입니다.', NULL, NULL, NULL, NULL),
  (59, 5, 'wsrep_local_recv_queue 해석하기', '`SHOW STATUS LIKE ''wsrep_local_recv_queue%''` 의 **평균값이 지속적으로 높습니다.** 무슨 신호일까요?', '이 큐는 "받았지만 아직 적용하지 못한 Write-Set"이 쌓이는 곳입니다.', NULL, NULL, '[]', 'choice', '["이 노드가 클러스터의 쓰기 속도를 **따라가지 못하고** 있다는 신호이다 (CPU·디스크 병목 의심, 심하면 Flow Control 로 클러스터 전체 쓰기가 느려진다)", "정상이다. 값이 높을수록 건강하다", "네트워크 선이 연결되지 않았다는 뜻이다", "노드가 클러스터에서 빠졌다는 뜻이다"]', 0, '0~1 이 정상입니다. 지속적으로 높으면 이 노드가 적용 속도를 소화하지 못하는 것이고, 계속 증가하면 **Flow Control** 이 발동해 클러스터 전체의 쓰기 속도가 이 노드에 맞춰 떨어집니다. 가장 느린 노드가 전체를 늦춘다는 점이 동기 복제의 특징입니다.', NULL, NULL, NULL, NULL),
  (59, 6, 'failover, switchover, split-brain 구분하기', 'Master 와 Slave 사이의 **네트워크가 끊겨서** Master 의 응답이 없습니다(실제로는 살아 있음). 이때 Slave 를 Master 로 승격하면 생길 수 있는 가장 위험한 문제는 무엇일까요?', 'Master 가 두 개가 되면 양쪽에 쓰기가 들어갑니다.', NULL, NULL, '[]', 'choice', '["Slave 의 CPU 가 낮아진다", "**Split-brain**: Master 가 둘이 되어 양쪽에 쓰기가 발생하고 데이터가 분기된다", "binlog 가 자동으로 삭제된다", "사용자가 많아진다"]', 1, '장애로 자동 전환되는 것이 **failover**, 사람이 계획해서 바꾸는 것이 **switchover** 입니다. failover 에서는 (1) 비동기 복제라면 마지막 데이터가 새 Master 에 없을 수 있고 (2) 네트워크 단절을 장애로 오판하면 **split-brain** 이 생깁니다. 그래서 정족수·펜싱 같은 장치가 필요합니다.', NULL, NULL, NULL, NULL),
  (59, 7, 'MaxScale 의 구성 요소 알기', 'MaxScale 에서 **SELECT 는 Slave 로, INSERT/UPDATE/DELETE 는 Master 로** 자동 분리해 주는 것은 어떤 구성 요소일까요?', 'MaxScale 은 Monitor, Router, Listener 세 가지로 구성됩니다.', NULL, NULL, '[]', 'choice', '["Monitor (`mariadbmon`, `galeramon`)", "Listener", "Router (`readwritesplit`)", "Binlog"]', 2, '**Monitor** 는 서버 상태(누가 Master 이고 살아 있는지)를 주기적으로 확인하고, **Router** 는 쿼리를 어디로 보낼지 결정하며(대표적으로 `readwritesplit`), **Listener** 는 클라이언트가 접속하는 포트를 엽니다. Master-Slave 에서는 `mariadbmon`, Galera 에서는 `galeramon` 을 씁니다. MaxScale 은 DB 를 대신해 복제하지 않고 앞단에서 트래픽만 제어합니다.', NULL, NULL, NULL, NULL),
  (59, 8, 'PITR(시점 복구) 순서 놓기', '실수로 테이블을 DROP 했습니다. 직전 시점으로 복구하는 **PITR** 순서를 앞에서 뒤로 놓으세요.', '풀 백업은 과거 시점입니다. 그 뒤의 변경은 로그로 되살립니다.', NULL, NULL, '[]', 'order', '["dump 이후부터 목표 시점 직전까지의 binlog 를 순서대로 replay 한다", "복구된 DB 가 원하는 시점의 상태인지 확인한다", "가장 가까운 과거 시점의 full dump 를 복원한다"]', NULL, '**full dump 복원 → dump 이후부터 목표 시점 직전까지 binlog replay(`mysqlbinlog --start-datetime ... --stop-datetime ...`) → 확인** 순서입니다. 풀 백업만으로는 최신 데이터를 살릴 수 없어서 변경 로그를 시간순으로 재실행합니다. 그래서 binlog 를 보관하는 것이 전제입니다.', '[2, 0, 1]', NULL, NULL, NULL),
  (59, 9, '복제 상태에서 확인할 필드 알기', 'Slave 에서 `SHOW SLAVE STATUS\\G` 를 실행했습니다. 복제가 **정상 동작 중인지** 가장 먼저 확인할 두 필드는 무엇일까요?', '복제에는 두 개의 스레드가 있습니다. 하나는 Master 에서 로그를 받아 오고, 하나는 그것을 적용합니다.', NULL, NULL, '[]', 'choice', '["`Master_Host` 와 `Master_User` 만 보면 된다", "`Binlog_Do_DB` 하나만 보면 된다", "필드는 볼 필요 없고 서버가 켜져 있으면 정상이다", "`Slave_IO_Running` 과 `Slave_SQL_Running` 이 모두 `Yes` 인지 (이상이면 `Last_Error` 류로 원인, `Seconds_Behind_Master` 로 지연 확인)"]', 3, 'IO 스레드(Master 에서 binlog 를 받아 오기)와 SQL 스레드(적용하기)가 둘 다 `Yes` 여야 정상입니다. 하나라도 `No` 면 `Last_IO_Error` / `Last_SQL_Error` 에 원인이 나옵니다. `Seconds_Behind_Master` 는 지연이 줄어드는 추이인지 봅니다. (MariaDB 10.5+ 는 `SHOW REPLICA STATUS` 도 동일하게 동작)', NULL, NULL, NULL, NULL),
  (59, 10, '복제 에러 임시 조치의 위험 알기', '복제가 `Last_SQL_Error: Table ''db.xxx'' doesn''t exist` 로 멈췄습니다. `SET GLOBAL gtid_slave_pos` 를 밀어서 **에러 트랜잭션을 건너뛰는** 조치에 대해 알맞은 것은 무엇일까요?', '건너뛴 트랜잭션은 Slave 에 적용되지 않습니다.', NULL, NULL, '[]', 'choice', '["급한 불을 끄는 **임시방편**일 뿐이다. 건너뛴 변경 때문에 Master 와 Slave 의 데이터가 어긋날 수 있어 반드시 이후에 데이터 검증이나 dump 재수행이 필요하다", "항상 안전한 정식 해결 방법이다", "Master 의 데이터도 같이 고쳐 준다", "건너뛰어도 데이터는 절대 어긋나지 않는다"]', 0, '에러 트랜잭션 skip(GTID 는 `gtid_slave_pos` 이동, non-GTID 는 `SQL_SLAVE_SKIP_COUNTER=1`)은 복제를 다시 돌게 할 뿐 **그 변경을 반영하지 않습니다.** 그래서 불일치를 만들 수 있습니다. 근본 해결은 dump 를 다시 받아 위치를 맞춰 재연결하는 것입니다.', NULL, NULL, NULL, NULL),
  (59, 11, 'dump 를 뜰 때 필수 옵션 알기', 'Slave 복구를 위해 Master 에서 `mariadb-dump`(또는 `mysqldump`)로 전체 dump 를 뜹니다. 아래 옵션의 역할로 알맞은 것은 무엇일까요?
